function increment(input: unknown): number | string {
    const data = input as { amount: number };
    return data.amount + 1;
}
console.log(increment(JSON.parse('{"amount":"7"}')));

function increment(input: unknown): number | string {
    if (typeof input !== 'object' || input === null || !('amount' in input)) return 'invalid';
    const amount = input.amount;
    if (typeof amount !== 'number' || !Number.isFinite(amount)) return 'invalid';
    return amount + 1;
}
console.log(increment(JSON.parse('{"amount":"7"}')));

async function count(): Promise<number> {
    let completed = 0;
    [1, 2].forEach(async () => {
        await Promise.resolve();
        completed += 1;
    });
    return completed;
}
console.log(await count());

async function count(): Promise<number> {
    let completed = 0;
    await Promise.all([1, 2].map(async () => {
        await Promise.resolve();
        completed += 1;
    }));
    return completed;
}
console.log(await count());

