package main

import "fmt"

type Labels struct { values []string }

// Snapshot returns an independent copy of the stored labels.
func (l *Labels) Snapshot() []string {
    return l.values
}

func main() {
    labels := &Labels{values: []string{"keep"}}
    result := labels.Snapshot()
    result[0] = "changed"
    fmt.Println(labels.values[0])
}

package main

import "fmt"

type Labels struct { values []string }

// Snapshot returns an independent copy of the stored labels.
func (l *Labels) Snapshot() []string {
    return append([]string(nil), l.values...)
}

func main() {
    labels := &Labels{values: []string{"keep"}}
    result := labels.Snapshot()
    result[0] = "changed"
    fmt.Println(labels.values[0])
}

