import "fmt"

type Record struct { ID int; Region string }
var snapshot = Record{ID: 42, Region: "west"}

func fetch(cached bool) Record {
    if cached {
        return Record{ID: snapshot.ID}
    }
    return snapshot
}

func main() {
    fmt.Printf("%s|%s\n", fetch(false).Region, fetch(true).Region)
}

