package main

import "fmt"

func retry(operation func() int) int {
    operation()
    return operation()
}

func main() {
    total := 0
    operation := func() int {
        for _, value := range []int{2, 3} {
            total += value
        }
        return total
    }
    fmt.Println(retry(operation))
}

