package main

import "fmt"

func compactID(value uint64) (uint32, bool) {
    if value > uint64(^uint32(0)) {
        return 0, false
    }
    return uint32(value), true
}

func main() {
    fmt.Println(compactID((uint64(1) << 32) + 9))
}

package main

func smallestID(ids map[int]struct{}) (int, bool) {
    for id := range ids {
        return id, true
    }
    return 0, false
}

package main

func smallestID(ids map[int]struct{}) (int, bool) {
    best, found := 0, false
    for id := range ids {
        if !found || id < best {
            best, found = id, true
        }
    }
    return best, found
}
